/**
 * pinmap.h - Signal name -> MCU pin. GENERATED BY HAND FROM docs/interface-control.md.
 *
 * Do not change a pin here without changing the ICD in the same PR (needs HW + FW review).
 * Names match the KiCad net labels.
 *
 * Pins marked DRAFT are carried over from VCU_2025 (Nucleo); everything else is TBD
 * until the 2027 schematic assigns it.
 */
#ifndef PINMAP_H
#define PINMAP_H

typedef enum {
    /* Digital inputs */
    SIG_NEUTRAL,
    SIG_REVERSE,
    SIG_DRIVE,
    SIG_L_SIGNAL_IN,
    SIG_R_SIGNAL_IN,
    SIG_HAZARD_IN,
    SIG_READY_MODE,
    SIG_CHARGE_MODE,
    SIG_THERMAL_SHUTOFF,
    SIG_BRAKE_PEDAL_IN,

    /* Digital outputs */
    SIG_BRAKE_LIGHT_OUT,
    SIG_L_SIGNAL_OUT,
    SIG_R_SIGNAL_OUT,
    SIG_DRL_LEFT_OUT,
    SIG_DRL_RIGHT_OUT,
    SIG_DASH_FAULT,
    SIG_HEARTBEAT_LED,

    SIG_COUNT
} signal_t;

/* Analog channels */
typedef enum {
    ADC_ACCEL_IN,        /* DRAFT: PA0 / ADC1_IN1 (VCU_2025) */
    ADC_SUP_BATT_MONITOR,
    ADC_COUNT
} adc_channel_t;

/*
 * Fixed / DRAFT peripheral pins (from VCU_2025):
 *   CAN_RX  PA11   CAN_TX  PA12
 *   USART2  PA2 (TX) / PA3 (RX)
 *   SWDIO   PA13   SWCLK   PA14   SWO PB3
 *   HSE     PF0 / PF1 (8 MHz crystal on the 2027 board)
 */

#endif /* PINMAP_H */
